const tabId = 825319308;

const houseListings = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/properties/"]'));
  const uniqueUrls = new Map();

  for (const a of links) {
    const url = a.href.split('#')[0];
    if (!uniqueUrls.has(url)) {
      // Find parent container or text around this link
      let container = a.closest('div[class*="propertyCard"], [class*="PropertyCard"], article, div[data-testid]');
      let text = container ? container.innerText : a.innerText;
      uniqueUrls.set(url, text);
    }
  }

  const results = [];
  for (const [url, text] of uniqueUrls.entries()) {
    results.push({ url, text: text.replace(/\n+/g, ' | ').slice(0, 300) });
  }
  return results;
});

