const pageInfo = await browserjs(tabId, () => {
  // Look for headings, search result counts, etc.
  const h1 = document.querySelector('h1')?.textContent?.trim();
  const sub = document.querySelector('[data-testid="results-count"], [aria-label*="places"], [aria-label*="stays"], h2, [data-section-id="EXPLORE_STRUCTURED_PAGE_TITLE"]')?.textContent?.trim();
  const bodyText = document.body.innerText;
  // Look for patterns like "X places", "Over 1,000 places", "X accommodations", etc.
  const matches = bodyText.match(/(?:over\s+)?[\d,]+\s+(?:places|stays|accommodations|homes|rentals)/gi);
  return {
    title: document.title,
    h1,
    sub,
    matches: matches ? Array.from(new Set(matches)).slice(0, 10) : []
  };
});

console.log("Airbnb search with dates:", pageInfo);

