// Use React prototype setter
const res = await browserjs(tabId, () => {
  const input = document.getElementById('locationInput');
  if (!input) return "No input found";

  input.focus();
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value").set;
  nativeInputValueSetter.call(input, "Barcelona");
  input.dispatchEvent(new Event('input', { bubbles: true }));
  input.dispatchEvent(new Event('change', { bubbles: true }));

  return { value: input.value };
});

console.log("React setter result:", res);

// Wait a second and check network or DOM
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

